test_suite:
test('allows up to limit concurrent acquires', async () => {
  const sem = new Semaphore(2);
  await sem.acquire();
  await sem.acquire();
  let resolved = false;
  const p = sem.acquire().then(() => { resolved = true; });
  await Promise.resolve();
  expect(resolved).toBe(false);
  sem.release();
  await p;
  expect(resolved).toBe(true);
});

test('release allows next waiter to proceed', async () => {
  const sem = new Semaphore(1);
  await sem.acquire();
  const order = [];
  const p = sem.acquire().then(() => order.push('second'));
  order.push('first');
  sem.release();
  await p;
  expect(order).toEqual(['first', 'second']);
});

// __hidden__
test('semaphore of limit 1 serializes tasks', async () => {
  const sem = new Semaphore(1);
  const results = [];
  async function task(id) {
    await sem.acquire();
    results.push(id);
    sem.release();
  }
  await Promise.all([task(1), task(2), task(3)]);
  expect(results.length).toBe(3);
});

solution:
export class Semaphore {
  constructor(limit) {
    this.limit = limit;
    this.count = 0;
    this.queue = [];
  }
  async acquire() {
    if (this.count < this.limit) {
      this.count++;
      return;
    }
    await new Promise(resolve => this.queue.push(resolve));
    this.count++;
  }
  release() {
    this.count--;
    if (this.queue.length > 0) {
      const next = this.queue.shift();
      next();
    }
  }
}
